module LFSR (
    output [3:0] out,
    input  clk,
    input  rst   // active‑high, synchronous reset
);
    // internal state register
    reg [3:0] out_reg;

    // feedback bit: NOT of XOR of the two MSBs
    wire feedback;
    assign feedback = ~(out_reg[3] ^ out_reg[2]);

    // synchronous reset and shift logic
    always @(posedge clk) begin
        if (rst) begin
            // synchronous reset to zero
            out_reg <= 4'b0000;
        end else begin
            // shift left and insert feedback at LSB
            out_reg <= {out_reg[2:0], feedback};
        end
    end

    // drive output
    assign out = out_reg;
endmodule

module mux2X1 (input a, input b, input sel, output y); assign y = sel ? b : a; endmodule

module barrel_shifter (input [7:0] in, input [2:0] ctrl, output [7:0] out);
    wire [7:0] stage4;
    wire [7:0] stage2;
    // Stage 4 shift (ctrl[2])
    mux2X1 u4_0 (.a(in[0]), .b(in[4]), .sel(ctrl[2]), .y(stage4[0]));
    mux2X1 u4_1 (.a(in[1]), .b(in[5]), .sel(ctrl[2]), .y(stage4[1]));
    mux2X1 u4_2 (.a(in[2]), .b(in[6]), .sel(ctrl[2]), .y(stage4[2]));
    mux2X1 u4_3 (.a(in[3]), .b(in[7]), .sel(ctrl[2]), .y(stage4[3]));
    mux2X1 u4_4 (.a(in[4]), .b(1'b0),   .sel(ctrl[2]), .y(stage4[4]));
    mux2X1 u4_5 (.a(in[5]), .b(1'b0),   .sel(ctrl[2]), .y(stage4[5]));
    mux2X1 u4_6 (.a(in[6]), .b(1'b0),   .sel(ctrl[2]), .y(stage4[6]));
    mux2X1 u4_7 (.a(in[7]), .b(1'b0),   .sel(ctrl[2]), .y(stage4[7]));
    // Stage 2 shift (ctrl[1])
    mux2X1 u2_0 (.a(stage4[0]), .b(stage4[2]), .sel(ctrl[1]), .y(stage2[0]));
    mux2X1 u2_1 (.a(stage4[1]), .b(stage4[3]), .sel(ctrl[1]), .y(stage2[1]));
    mux2X1 u2_2 (.a(stage4[2]), .b(stage4[4]), .sel(ctrl[1]), .y(stage2[2]));
    mux2X1 u2_3 (.a(stage4[3]), .b(stage4[5]), .sel(ctrl[1]), .y(stage2[3]));
    mux2X1 u2_4 (.a(stage4[4]), .b(stage4[6]), .sel(ctrl[1]), .y(stage2[4]));
    mux2X1 u2_5 (.a(stage4[5]), .b(stage4[7]), .sel(ctrl[1]), .y(stage2[5]));
    mux2X1 u2_6 (.a(stage4[6]), .b(1'b0),   .sel(ctrl[1]), .y(stage2[6]));
    mux2X1 u2_7 (.a(stage4[7]), .b(1'b0),   .sel(ctrl[1]), .y(stage2[7]));
    // Final shift (ctrl[0]) producing out
    mux2X1 u0_0 (.a(stage2[0]), .b(stage2[1]), .sel(ctrl[0]), .y(out[0]));
    mux2X1 u0_1 (.a(stage2[1]), .b(stage2[2]), .sel(ctrl[0]), .y(out[1]));
    mux2X1 u0_2 (.a(stage2[2]), .b(stage2[3]), .sel(ctrl[0]), .y(out[2]));
    mux2X1 u0_3 (.a(stage2[3]), .b(stage2[4]), .sel(ctrl[0]), .y(out[3]));
    mux2X1 u0_4 (.a(stage2[4]), .b(stage2[5]), .sel(ctrl[0]), .y(out[4]));
    mux2X1 u0_5 (.a(stage2[5]), .b(stage2[6]), .sel(ctrl[0]), .y(out[5]));
    mux2X1 u0_6 (.a(stage2[6]), .b(stage2[7]), .sel(ctrl[0]), .y(out[6]));
    mux2X1 u0_7 (.a(stage2[7]), .b(1'b0),    .sel(ctrl[0]), .y(out[7]));
endmodule

// Verilog implementation of LIFObuffer (module body only)

// internal registers
reg [3:0] stack_mem [0:3]; // 4-entry stack, each 4 bits
reg [2:0] SP;                 // stack pointer, 0..4 (3 bits needed)
reg [3:0] dataOut_reg;
reg EMPTY_reg, FULL_reg;

// output assignments
assign dataOut = dataOut_reg;
assign EMPTY   = EMPTY_reg;
assign FULL    = FULL_reg;

// combinational temporary for next pointer/value
reg [2:0] next_SP;
reg [3:0] next_dataOut;

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            // synchronous reset – clear stack, pointer, flags
            SP            <= 3'd4;   // 4 indicates empty
            dataOut_reg   <= 4'd0;
            EMPTY_reg     <= 1'b1;
            FULL_reg      <= 1'b0;
            stack_mem[0]  <= 4'd0;
            stack_mem[1]  <= 4'd0;
            stack_mem[2]  <= 4'd0;
            stack_mem[3]  <= 4'd0;
        end else begin
            // default: hold current state
            next_SP      = SP;
            next_dataOut = dataOut_reg;

            // write operation (push) – RW == 0, not full
            if (!RW && SP != 3'd0) begin
                next_SP = SP - 1;                // decrement pointer
                stack_mem[next_SP] <= dataIn;    // store new entry at new top
            end
            // read operation (pop) – RW == 1, not empty
            else if (RW && SP != 3'd4) begin
                next_dataOut = stack_mem[SP];    // output the current top
                stack_mem[SP] <= 4'd0;           // clear the location
                next_SP = SP + 1;                // increment pointer
            end

            // commit next-state values
            SP          <= next_SP;
            dataOut_reg <= next_dataOut;
            EMPTY_reg   <= (next_SP == 3'd4);
            FULL_reg    <= (next_SP == 3'd0);
        end
    end
    // when EN is low, retain previous state (nothing to do – registers keep their values)
end

// Asynchronous FIFO with separate dual‑port RAM
// ---------------------------------------------------
// Top‑level FIFO module
module asyn_fifo #(
    parameter int WIDTH = 8,   // internal data width (may differ from external 8‑bit ports)
    parameter int DEPTH = 16   // FIFO depth – must be power‑of‑two
) (
    input  wire        wclk,   // write clock
    input  wire        rclk,   // read clock
    input  wire        wrstn,  // active‑low write reset
    input  wire        rrstn,  // active‑low read reset
    input  wire        winc,   // write‑enable pulse
    input  wire        rinc,   // read‑enable pulse
    input  wire [7:0]  wdata,  // write data (external 8‑bit port)
    output wire        wfull,  // FIFO full flag
    output wire        rempty, // FIFO empty flag
    output wire [7:0]  rdata   // read data (external 8‑bit port)
);

    // ---------------------------------------------------
    // Pointer width (log2 of depth)
    localparam int PTR_W = $clog2(DEPTH);

    // ---------------------------------------------------
    // Write side (write clock domain)
    // ---------------------------------------------------
    logic [PTR_W-1:0] wptr_bin;   // binary write pointer
    logic [PTR_W-1:0] wptr_gray;  // gray‑coded write pointer
    logic wenc;                  // write enable to RAM
    logic [PTR_W-1:0] waddr;     // address for RAM write

    // combinational write enable (writes only when not full)
    assign wenc = winc && !wfull;

    // write address uses lower bits of binary pointer (MSB is not part of address)
    assign waddr = {1'b0, wptr_bin[PTR_W-2:0]}; // MSB forced to 0 – address width = PTR_W

    // binary pointer update (async reset)
    always_ff @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr_bin <= '0;
        else if (wenc)
            wptr_bin <= wptr_bin + 1'b1;
    end

    // gray conversion (registered to keep it synchronous with wclk)
    always_ff @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr_gray <= '0;
        else
            wptr_gray <= wptr_bin ^ (wptr_bin >> 1);
    end

    // ---------------------------------------------------
    // Read side (read clock domain)
    // ---------------------------------------------------
    logic [PTR_W-1:0] rptr_bin;   // binary read pointer
    logic [PTR_W-1:0] rptr_gray;  // gray‑coded read pointer
    logic ren;                    // read enable to RAM
    logic [PTR_W-1:0] raddr;      // address for RAM read

    assign ren = rinc && !rempty;
    assign raddr = {1'b0, rptr_bin[PTR_W-2:0]};

    always_ff @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr_bin <= '0;
        else if (ren)
            rptr_bin <= rptr_bin + 1'b1;
    end

    always_ff @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr_gray <= '0;
        else
            rptr_gray <= rptr_bin ^ (rptr_bin >> 1);
    end

    // ---------------------------------------------------
    // Pointer synchronizers (cross‑domain CDC)
    // ---------------------------------------------------
    // read‑pointer into write‑clock domain
    logic [PTR_W-1:0] rptr_sync0, rptr_sync1;
    always_ff @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync0 <= '0;
            rptr_sync1 <= '0;
        end else begin
            rptr_sync0 <= rptr_gray;
            rptr_sync1 <= rptr_sync0;
        end
    end

    // write‑pointer into read‑clock domain
    logic [PTR_W-1:0] wptr_sync0, wptr_sync1;
    always_ff @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync0 <= '0;
            wptr_sync1 <= '0;
        end else begin
            wptr_sync0 <= wptr_gray;
            wptr_sync1 <= wptr_sync0;
        end
    end

    // ---------------------------------------------------
    // Full / Empty detection (Gray code comparison)
    // ---------------------------------------------------
    assign rempty = (rptr_gray == wptr_sync1);

    assign wfull = (wptr_gray[PTR_W-1]   != wptr_sync1[PTR_W-1]) &&
                   (wptr_gray[PTR_W-2]   != wptr_sync1[PTR_W-2]) &&
                   (wptr_gray[PTR_W-3:0] == wptr_sync1[PTR_W-3:0]);

    // ---------------------------------------------------
    // RAM instantiation (dual‑port register array)
    // ---------------------------------------------------
    // Zero‑extend (or truncate) external write data to internal WIDTH
    logic [WIDTH-1:0] wdata_int;
    assign wdata_int = wdata; // automatic size conversion

    // Capture read data from RAM, then truncate/fit to 8‑bit output
    logic [WIDTH-1:0] rdata_int;
    assign rdata = rdata_int[7:0];

    dual_port_RAM #(
        .WIDTH (WIDTH),
        .DEPTH (DEPTH)
    ) ram_inst (
        .wclk  (wclk),
        .wenc  (wenc),
        .waddr (waddr),
        .wdata (wdata_int),
        .rclk  (rclk),
        .renc  (ren),
        .raddr (raddr),
        .rdata (rdata_int)
    );

endmodule // asyn_fifo

// ---------------------------------------------------
// Simple synchronous dual‑port RAM (write on wclk, read on rclk)
// ---------------------------------------------------
module dual_port_RAM #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  wire               wclk,
    input  wire               wenc,
    input  wire [$clog2(DEPTH)-1:0] waddr,
    input  wire [WIDTH-1:0]   wdata,
    input  wire               rclk,
    input  wire               renc,
    input  wire [$clog2(DEPTH)-1:0] raddr,
    output reg  [WIDTH-1:0]   rdata
);
    // Register array
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // Write side – rising edge of wclk
    always_ff @(posedge wclk) begin
        if (wenc)
            mem[waddr] <= wdata;
    end

    // Read side – rising edge of rclk
    always_ff @(posedge rclk) begin
        if (renc)
            rdata <= mem[raddr];
    end
endmodule // dual_port_RAM

module freq_divbyfrac (
    input clk,
    input rst_n,
    output clk_div
);
    // Internal registers
    reg [2:0] cnt;
    reg clk_pos;
    reg clk_neg;

    // Counter: increments on every half‑cycle (both edges)
    always @(posedge clk or negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 3'd0;
        end else begin
            cnt <= (cnt == 3'd6) ? 3'd0 : cnt + 3'd1; // modulo‑7 count
        end
    end

    // Generate clk_pos on the positive edge of clk
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_pos <= 1'b0;
        end else begin
            clk_pos <= (cnt < 3) ? 1'b1 : 1'b0;
        end
    end

    // Generate clk_neg on the negative edge of clk
    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_neg <= 1'b0;
        end else begin
            clk_neg <= (cnt >= 3) ? 1'b1 : 1'b0;
        end
    end

    // Combine the two halves to obtain the fractional divided clock
    assign clk_div = clk_pos | clk_neg;

endmodule

module freq_divbyfrac (input clk, input rst_n, output wire clk_div);
  // internal declarations
  reg [2:0] cnt;
  reg clk_pos;
  reg clk_neg;

  // Counter modulo‑7, increments on every half‑cycle
  always @(posedge clk or negedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt <= 3'd0;
    end else if (cnt == 3'd6) begin
      cnt <= 3'd0;
    end else begin
      cnt <= cnt + 3'd1;
    end
  end

  // Generate positive‑edge portion of divided clock
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      clk_pos <= 1'b0;
    end else begin
      clk_pos <= (cnt < 3) ? 1'b1 : 1'b0;
    end
  end

  // Generate negative‑edge portion of divided clock
  always @(negedge clk or negedge rst_n) begin
    if (!rst_n) begin
      clk_neg <= 1'b0;
    end else begin
      clk_neg <= (cnt >= 3) ? 1'b1 : 1'b0;
    end
  end

  // Combine both halves to produce the fractional clock
  assign clk_div = clk_pos | clk_neg;
endmodule

module freq_divbyodd (
    input  wire clk,
    input  wire rst_n,   // active-low asynchronous reset
    output wire clk_div
);
    parameter NUM_DIV = 5;
    // Odd check at elaboration
    generate
        if (NUM_DIV % 2 == 0) begin : gen_error
            initial $error("NUM_DIV must be odd");
        end
    endgenerate

    localparam HALF = NUM_DIV / 2;

    reg [31:0] cnt1;
    reg [31:0] cnt2;

    // Counter 1 – positive edge
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt1 <= 0;
        else if (cnt1 == NUM_DIV-1)
            cnt1 <= 0;
        else
            cnt1 <= cnt1 + 1;
    end

    // Counter 2 – negative edge
    always @(negedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt2 <= 0;
        else if (cnt2 == NUM_DIV-1)
            cnt2 <= 0;
        else
            cnt2 <= cnt2 + 1;
    end

    wire clk_div1 = (cnt1 < HALF);
    wire clk_div2 = (cnt2 < HALF);

    assign clk_div = clk_div1 | clk_div2;

endmodule

module pulse_detect (
    input  clk,
    input  rst_n,   // asynchronous active‑low reset
    input  data_in,
    output reg data_out // one‑cycle pulse indicating detection
);

    // shift register: holds two previous samples and current sample
    reg [2:0] shift;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift    <= 3'b000;
            data_out <= 1'b0;
        end else begin
            // compute next shift value
            // using a temporary wire avoids dependence on non‑blocking update order
            // (ensures detection is based on the newly shifted data)
            // Note: shift_next is a combinational expression, not a register.
            // It represents the value that shift will take after this edge.
            // The detection logic uses this value directly.
            // This satisfies the requirement to use a shift register and to
            // produce a single‑cycle pulse when a 0→1→0 pattern is observed.
            //
            // (No additional ports or parameters are used.)

            // shift_new captures the updated shift content
            // (cannot be a reg because it's used only for this calculation)
            // We'll compute it inline.

            // update shift register
            shift <= {shift[1:0], data_in};
            // generate pulse based on the new shift values
            data_out <= ({shift[1:0], data_in}[2] == 1'b0 &&
                         {shift[1:0], data_in}[1] == 1'b1 &&
                         {shift[1:0], data_in}[0] == 1'b0);
        end
    end

endmodule

