reg [31:0] sum;

// Drive the output with the accumulator value
assign c = sum;

// Asynchronous active‑high reset, multiply‑accumulate on each clock cycle
always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum <= 32'b0;          // reset accumulator to zero
    end else begin
        sum <= sum + (a * b); // accumulate product of a and b
    end
end

