            ADD: begin
                res       = add_ext[31:0];
                carry_reg = add_ext[32];
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res       = add_ext[31:0];
                carry_reg = add_ext[32];
                overflow_reg = 1'b0;
            end
            SUB: begin
                res       = sub_ext[31:0];
                carry_reg = a < b; // borrow
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res       = sub_ext[31:0];
                carry_reg = a < b; // borrow for unsigned
                overflow_reg = 1'b0;
            end
            AND:  res = a & b;
            OR:   res = a | b;
            XOR:  res = a ^ b;
            NOR:  res = ~(a | b);
            SLT: begin
