module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    // opcode parameters
    parameter ADD   = 6'b100000;
    parameter ADDU  = 6'b100001;
    parameter SUB   = 6'b100010;
    parameter SUBU  = 6'b100011;
    parameter AND   = 6'b100100;
    parameter OR    = 6'b100101;
    parameter XOR   = 6'b100110;
    parameter NOR   = 6'b100111;
    parameter SLT   = 6'b101010;
    parameter SLTU  = 6'b101011;
    parameter SLL   = 6'b000000;
    parameter SRL   = 6'b000010;
    parameter SRA   = 6'b000011;
    parameter SLLV  = 6'b000100;
    parameter SRLV  = 6'b000110;
    parameter SRAV  = 6'b000111;
    parameter LUI   = 6'b001111;

    reg [31:0] result;
    reg carry_out;
    reg overflow_flag;
    reg flag_out;

    // combinational logic
    always @* begin
        // defaults
        result = 32'b0;
        carry_out = 1'b0;
        overflow_flag = 1'b0;
        flag_out = 1'b0;
        case (aluc)
            ADD: begin
                {carry_out, result} = a + b;
                overflow_flag = (a[31] == b[31]) && (result[31] != a[31]);
            end
            ADDU: begin
                {carry_out, result} = a + b;
                overflow_flag = 1'b0;
            end
            SUB: begin
                {carry_out, result} = a - b; // carry_out is NOT borrow
                carry_out = ~carry_out; // convert to borrow flag
                overflow_flag = (a[31] != b[31]) && (result[31] != a[31]);
            end
            SUBU: begin
                {carry_out, result} = a - b;
                carry_out = ~carry_out; // borrow flag
                overflow_flag = 1'b0;
            end
            AND: result = a & b;
            OR:  result = a | b;
            XOR: result = a ^ b;
            NOR: result = ~(a | b);
            SLT: begin
                flag_out = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
                result = 32'b0;
            end
            SLTU: begin
                flag_out = (a < b) ? 1'b1 : 1'b0;
                result = 32'b0;
            end
            SLL: result = b << a[4:0];
