# The following is a Verilog implementation of an 8‑bit shift‑and‑add multiplier.
# It uses a generate block to create the eight partial products (multiplicand A
# shifted left by the index of each set bit of multiplier B) and then adds them
# together.  The final 16‑bit product is driven by a continuous assign statement.
module multi_8bit (
    input  [7:0] A,
    input  [7:0] B,
    output [15:0] product
);

    // ---------------------------------------------------------------------
    // Partial products: each term is A shifted left by i bits, enabled by B[i]
    // ---------------------------------------------------------------------
    wire [15:0] pp [0:7];
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen_pp
            // Left‑shifted multiplicand, masked by the corresponding multiplier bit
            assign pp[i] = B[i] ? ({8'b0, A} << i) : 16'b0;
        end
    endgenerate

    // ---------------------------------------------------------------------
    // Reduce the partial products with a simple adder tree (fully combinational)
    // ---------------------------------------------------------------------
    wire [15:0] sum0 = pp[0] + pp[1];
    wire [15:0] sum1 = sum0 + pp[2];
    wire [15:0] sum2 = sum1 + pp[3];
    wire [15:0] sum3 = sum2 + pp[4];
    wire [15:0] sum4 = sum3 + pp[5];
    wire [15:0] sum5 = sum4 + pp[6];
    wire [15:0] sum6 = sum5 + pp[7];

    // Final product driven by a continuous assignment
    assign product = sum6;

endmodule

