/*
 * Parameterized signed fixed‑point adder (two's‑complement)
 * Q : number of fractional bits (0 ≤ Q < N)
 * N : total bit‑width, MSB is the sign bit
 *
 * Behaviour (combinational):
 *   – If the signs of a and b are equal, perform a normal two's‑complement addition.
 *   – If the signs differ, subtract the smaller magnitude from the larger magnitude.
 *     The sign of the result follows the operand with the larger absolute value.
 *   – The design wraps around on overflow (standard two's‑complement arithmetic).
 *   – An internal overflow flag is calculated for documentation purposes only.
 */
module fixed_point_adder #(
    parameter Q = 15,               // number of fractional bits (0 ≤ Q < N)
    parameter N = 32                // total bit‑width, MSB is the sign bit
) (
    input  [N-1:0] a,               // first operand, two's‑complement signed
    input  [N-1:0] b,               // second operand, two's‑complement signed
    output [N-1:0] c                // N‑bit signed result
);

    // ---------------------------------------------------------------------
    // Internal combinational register that holds the result before it is
    // driven to the output.  It is purely combinational – no clock is used.
    // ---------------------------------------------------------------------
    reg [N-1:0] res;

    // ---------------------------------------------------------------------
    // Helper wires: absolute values of the operands (unsigned magnitude).  The
    // two's‑complement absolute value is computed as:
    //   abs(x) = (x[N-1] ? (~x + 1'b1) : x);
    // ---------------------------------------------------------------------
    wire [N-1:0] abs_a = a[N-1] ? (~a + 1'b1) : a;
    wire [N-1:0] abs_b = b[N-1] ? (~b + 1'b1) : b;

    // ---------------------------------------------------------------------
    // Optional overflow flag (for readability only).  Overflow occurs only
    // when adding two numbers of the same sign and the sign of the sum differs
    // from the operands' sign.
    // ---------------------------------------------------------------------
    wire overflow = (a[N-1] == b[N-1]) && ( (a[N-1] == 1'b0 && res[N-1] == 1'b1) ||
                                            (a[N-1] == 1'b1 && res[N-1] == 1'b0) );

    // ---------------------------------------------------------------------
    // Main combinational logic – computes `res` according to the specification.
    // ---------------------------------------------------------------------
    always @* begin
        // Default value – protects against latches.
        res = {N{1'b0}};

        // Case 1: both operands have the same sign → simple addition.
        if (a[N-1] == b[N-1]) begin
            res = a + b;               // two's‑complement addition, wraps on overflow
        end else begin
            // Case 2: opposite signs → subtract the smaller magnitude from the larger.
            if (abs_a > abs_b) begin
                // |a| > |b| → result follows the sign of `a`.
                // Using subtraction yields the correct signed result.
                res = a - b;
            end else if (abs_b > abs_a) begin
                // |b| > |a| → result follows the sign of `b`.
                res = b - a;
            end else begin
                // |a| == |b| → result is exactly zero.
                res = {N{1'b0}};
            end
        end
    end

    // Drive the output.
    assign c = res;

    // The overflow flag is kept as a comment only – it can be hooked to a debug
    // port if desired, but it is not part of the required interface.
    // (* keep = "true" *) // synthesis directive placeholder (optional)
    // assign overflow_flag = overflow; // Uncomment to expose the flag.

endmodule

reg [N-1:0] res;

// internal signed versions for convenience
wire signed [N-1:0] sa = $signed(a);
wire signed [N-1:0] sb = $signed(b);

// sign bits
wire sign_a = a[N-1];
wire sign_b = b[N-1];

// absolute (magnitude) values in two's‑complement form
wire [N-1:0] abs_a = sign_a ? (~a + 1'b1) : a;   // if negative, take two's‑complement
wire [N-1:0] abs_b = sign_b ? (~b + 1'b1) : b;

always @* begin
    if (sign_a == sign_b) begin               // same sign → add magnitudes
        // add the absolute values; overflow is truncated
        res = {sign_a, (abs_a[N-2:0] + abs_b[N-2:0])};
    end else begin                            // different signs → subtract magnitudes
        if (abs_a >= abs_b) begin
            // |a| >= |b| → result sign follows a
            res = {sign_a, (abs_a[N-2:0] - abs_b[N-2:0])};
        end else begin
            // |b| > |a| → result sign follows b
            // result is zero when the magnitudes are equal (handled above)
            res = {sign_b, (abs_b[N-2:0] - abs_a[N-2:0])};
        end
