    reg [23:0] mant_pre;           // mantissa (hidden‑1 + 23 bits) before rounding
    reg        lsb;                // least‑significant mantissa bit before rounding
    reg        round_inc;          // round‑to‑nearest‑even increment (0/1)
    reg [24:0] mant_sum;           // mant_pre + round_inc (may overflow)
    reg [23:0] mant_rounded;       // mantissa after rounding (still with hidden‑1)
    reg [9:0]  exp_adj;            // exponent after rounding (may be incremented)

    // ---------------------------------------------------------------------
    //  Synchronous reset – clear every register to a known value.
    // ---------------------------------------------------------------------
    always @(posedge clk) begin
        if (rst) begin
            counter        <= 3'd0;
            a_sign         <= 1'b0;  b_sign         <= 1'b0;  z_sign         <= 1'b0;
            a_exponent     <= 10'd0; b_exponent     <= 10'd0; z_exponent     <= 10'd0;
            a_mantissa     <= 24'd0; b_mantissa     <= 24'd0; z_mantissa     <= 24'd0;
            product        <= 50'd0;
            guard_bit      <= 1'b0;  round_bit      <= 1'b0;  sticky      <= 1'b0;
            a_is_nan       <= 1'b0;  b_is_nan       <= 1'b0;
            a_is_inf       <= 1'b0;  b_is_inf       <= 1'b0;
            a_is_zero      <= 1'b0;  b_is_zero      <= 1'b0;
            raw_exponent   <= 10'd0;
            mant_pre       <= 24'd0;
            lsb            <= 1'b0;
            round_inc      <= 1'b0;
            mant_sum       <= 25'd0;
            mant_rounded   <= 24'd0;
            exp_adj        <= 10'd0;
            z_reg          <= 32'd0;
        end else begin
            case (counter)
                // -----------------------------------------------------------
                // 0 : EXTRACT – split the inputs into sign, exponent, mantissa
                // -----------------------------------------------------------
                3'd0: begin
                    // sign bits
                    a_sign <= a[31];
                    b_sign <= b[31];

                    // raw exponents (8‑bit) – zero‑extend to 10 bits for later maths
                    a_exponent[7:0] <= a[30:23];
                    b_exponent[7:0] <= b[30:23];
                    a_exponent[9:8] <= 2'b00;
                    b_exponent[9:8] <= 2'b00;

                    // raw mantissas (23 bits)
                    a_mantissa[22:0] <= a[22:0];
                    b_mantissa[22:0] <= b[22:0];

                    // detect the IEEE‑754 special cases for each operand
                    a_is_nan   <= (a[30:23] == 8'hFF) && (a[22:0] != 23'd0);
                    b_is_nan   <= (b[30:23] == 8'hFF) && (b[22:0] != 23'd0);
                    a_is_inf   <= (a[30:23] == 8'hFF) && (a[22:0] == 23'd0);
                    b_is_inf   <= (b[30:23] == 8'hFF) && (b[22:0] == 23'd0);
                    a_is_zero  <= (a[30:23] == 8'd0) && (a[22:0] == 23'd0);
                    b_is_zero  <= (b[30:23] == 8'd0) && (b[22:0] == 23'd0);

                    // implicit leading "1" for normal numbers – "0" for sub‑normals
                    a_mantissa[23] <= (a[30:23] == 8'd0) ? 1'b0 : 1'b1;
                    b_mantissa[23] <= (b[30:23] == 8'd0) ? 1'b0 : 1'b1;

                    counter <= counter + 1'b1; // move to MULT stage
                end

                // -----------------------------------------------------------
                // 1 : MULT – 24‑bit mantissas are multiplied, exponent bias is removed
                // -----------------------------------------------------------
                3'd1: begin
                    // Unsigned multiplication of the 24‑bit mantissas (including hidden bit)
                    product <= a_mantissa * b_mantissa; // 48‑bit product, kept in a 50‑bit reg

                    // raw exponent = a_exp + b_exp - bias (127)
                    raw_exponent <= a_exponent + b_exponent - 10'd127;

                    counter <= counter + 1'b1; // move to NORM stage
                end

                // -----------------------------------------------------------
                // 2 : NORM – left‑shift if the most‑significant product bit is 0
                // -----------------------------------------------------------
                3'd2: begin
                    if (product[47] == 1'b0) begin
                        // shift left by one, decrement exponent to keep the value the same
                        product      <= product << 1;
                        raw_exponent <= raw_exponent - 1'b1;
                    end
                    // otherwise product already has the hidden‑1 at bit 47
                    counter <= counter + 1'b1; // move to ROUND stage
                end

                // -----------------------------------------------------------
                // 3 : ROUND – extract guard/round/sticky bits and perform
                //           round‑to‑nearest‑even on the mantissa.
                // -----------------------------------------------------------
                3'd3: begin
                    // Guard, round and sticky bits as defined in the description
                    guard_bit <= product[23];                     // first bit to be discarded
                    round_bit <= product[22];                     // second bit to be discarded
                    sticky    <= |product[21:0];                 // OR of all remaining bits

                    // Build the 24‑bit mantissa that still contains the hidden "1"
                    //   product[47] is guaranteed to be 1 after the normalisation step.
                    mant_pre <= {1'b1, product[46:24]};           // {hidden, 23 fraction bits}
                    lsb      <= product[24];                      // LSB of the fraction before rounding

                    // Round‑to‑nearest‑even increment logic
                    round_inc <= guard_bit & (round_bit | sticky | lsb);

                    // Add the increment – 25 bits are required to capture a possible carry
                    mant_sum <= mant_pre + round_inc;

                    // If the addition produced a carry out of bit 23, shift right and
                    // increment the exponent (this is the "mantissa overflow" case).
                    if (mant_sum[24] == 1'b1) begin
                        mant_rounded <= mant_sum[24:1]; // shift right, hidden‑1 stays 1
                        exp_adj      <= raw_exponent + 1'b1;
                    end else begin
                        mant_rounded <= mant_sum[23:0]; // no overflow – keep as‑is
                        exp_adj      <= raw_exponent;
                    end

                    // Remember the sign of the product – XOR of the operand signs.
                    // The final sign may be overwritten later by NaN handling.
                    z_sign <= a_sign ^ b_sign;

                    counter <= counter + 1'b1; // move to DONE stage
                end

                // -----------------------------------------------------------
                // 4 : DONE – assemble the final IEEE‑754 word, handling all special
                //           cases with the required priority order.
                // -----------------------------------------------------------
                3'd4: begin
                    // -----------------------------------------------------------------
                    // 1) NaN has the highest priority
                    // -----------------------------------------------------------------
                    if (a_is_nan || b_is_nan) begin
                        z_sign     <= 1'b0;               // sign of NaN is conventionally 0
                        z_exponent <= 10'd255;            // all 1's (8‑bit field after truncation)
                        // quiet NaN: most‑significant mantissa bit = 1, rest = 0
                        z_mantissa <= 24'h400000;        // 1 followed by 23 zeros (includes hidden bit)
                    end
                    // -----------------------------------------------------------------
                    // 2) Infinity × Zero → NaN (the sign does not matter)
                    // -----------------------------------------------------------------
                    else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z_sign     <= 1'b0;
                        z_exponent <= 10'd255;
                        z_mantissa <= 24'h400000; // quiet NaN
                    end
                    // -----------------------------------------------------------------
                    // 3) Infinity (any non‑zero operand) → Infinity
                    // -----------------------------------------------------------------
                    else if (a_is_inf || b_is_inf) begin
                        z_sign     <= a_sign ^ b_sign;
                        z_exponent <= 10'd255;            // all 1's -> Infinity
                        z_mantissa <= 24'd0;              // zero mantissa
                    end
                    // -----------------------------------------------------------------
                    // 4) Zero (any operand) → Zero (preserve sign of the product)
                    // -----------------------------------------------------------------
                    else if (a_is_zero || b_is_zero) begin
                        z_sign     <= a_sign ^ b_sign;
                        z_exponent <= 10'd0;              // exponent = 0
                        z_mantissa <= 24'd0;              // mantissa = 0 (sub‑normal zero)
                    end
                    // -----------------------------------------------------------------
                    // 5) Normal result – apply exponent limits and assemble
                    // -----------------------------------------------------------------
                    else begin
                        // Apply the exponent that resulted from rounding
                        // (exp_adj already contains the possible +1 from overflow).
                        // Saturate according to IEEE‑754 limits.
                        if (exp_adj >= 10'd255) begin // overflow → Infinity
                            z_exponent <= 10'd255;
                            z_mantissa <= 24'd0;
                        end else if (exp_adj <= 10'd0) begin // underflow → Zero
                            z_exponent <= 10'd0;
                            z_mantissa <= 24'd0;
                        end else begin
                            z_exponent <= exp_adj;               // normal exponent (8‑bit after trunc)
                            // Drop the hidden bit – only the low 23 bits go to the output
                            z_mantissa <= mant_rounded;          // contains hidden‑1 at bit 23
                        end
                    end

                    // -----------------------------------------------------------------
                    // Assemble the final 32‑bit IEEE‑754 word and register it.
                    // -----------------------------------------------------------------
                    // The exponent field used on the wire is only the low 8 bits of the
                    // 10‑bit internal exponent register; the upper two bits are never
                    // needed for a single‑precision result.
                    z_reg <= { z_sign,
                               z_exponent[7:0],
                               z_mantissa[22:0] };

                    // Return to the IDLE (EXTRACT) state for the next multiplication.
                    counter <= 3'd0;
                end

                default: counter <= 3'd0; // safety fallback
            endcase
        end
    end

endmodule
```

