```systemverilog
module div_16bit (
    input  [15:0] A,   // 16‑bit dividend
    input  [7:0]  B,   // 8‑bit divisor
    output [15:0] result, // 16‑bit quotient
    output [15:0] odd      // 16‑bit remainder
);
