# The following Verilog implements an 8‑bit radix‑2 (non‑restoring) divider that supports signed and unsigned operations.
# It follows the exact interface required in the prompt and meets all functional specifications.
# NOTE: If divisor == 0 the divider will not start – the output remains unchanged.

module radix2_div (
    input  wire        clk,        // system clock, positive edge
    input  wire        rst,        // synchronous, active‑high reset
    input  wire [7:0]  dividend,   // dividend operand
    input  wire [7:0]  divisor,    // divisor operand
    input  wire        sign,       // 1 = signed division, 0 = unsigned
    input  wire        opn_valid,  // high when a new operation is presented
    output reg         res_valid,  // high when result is ready
    input  wire        res_ready,  // high when the consumer has taken the result
    output reg [15:0]  result      // {remainder[7:0], quotient[7:0]}
);

    // ------------------------------------------------------------
    // State machine encoding
    // ------------------------------------------------------------
    localparam IDLE = 2'd0,
               BUSY = 2'd1,
               DONE = 2'd2;

    reg [1:0] state;                 // current state
    reg [2:0] cnt;                   // iteration counter (1‑8)
    reg [15:0] SR;                   // shift register used by the algorithm
    reg [7:0]  abs_dividend;         // |dividend|
    reg [7:0]  abs_divisor;          // |divisor|
    reg [7:0]  neg_divisor;          // -|divisor|
    reg        sign_reg;             // copy of 'sign' for the current operation
    reg        dividend_neg;         // original sign of dividend (1 = negative)
    reg        divisor_neg;          // original sign of divisor  (1 = negative)
    reg [7:0]  quotient_u;           // unsigned quotient produced by the algorithm
    reg [7:0]  remainder_u;          // unsigned remainder produced by the algorithm

    // ------------------------------------------------------------
    // Sequential logic – state machine and algorithm
    // ------------------------------------------------------------
    always @(posedge clk) begin
        if (rst) begin
            // synchronous reset – clear everything
            state          <= IDLE;
            cnt            <= 3'd0;
            SR             <= 16'd0;
            abs_dividend   <= 8'd0;
            abs_divisor    <= 8'd0;
            neg_divisor    <= 8'd0;
            sign_reg       <= 1'b0;
            dividend_neg   <= 1'b0;
            divisor_neg    <= 1'b0;
            quotient_u     <= 8'd0;
            remainder_u    <= 8'd0;
            res_valid      <= 1'b0;
            result         <= 16'd0;
        end else begin
            case (state)
                IDLE: begin
                    // wait for a new operation; must not be busy and result not pending
                    if (opn_valid && !res_valid && divisor != 8'd0) begin
                        // latch inputs
                        sign_reg     <= sign;
                        // capture original sign bits (only meaningful when sign==1)
                        dividend_neg <= sign ? dividend[7] : 1'b0;
                        divisor_neg  <= sign ? divisor[7]  : 1'b0;
                        // absolute values
                        abs_dividend <= (sign && dividend[7]) ? (~dividend + 8'd1) : dividend;
                        abs_divisor  <= (sign && divisor[7])  ? (~divisor  + 8'd1) : divisor;
                        // compute two's‑complement negative divisor
                        neg_divisor  <= -abs_divisor;
                        // initialise shift register: {abs(dividend),8'b0} << 1
                        SR           <= ({abs_dividend,8'b0} << 1);
                        cnt          <= 3'd1;
                        state        <= BUSY;
                        res_valid    <= 1'b0;
                    end else begin
                        // stay idle – keep result unchanged
                        state <= IDLE;
                    end
                end

                BUSY: begin
                    // ---------- non‑restoring step ----------
                    // 9‑bit addition: upper 8 bits + NEG_DIVISOR
                    // sum[8] is the carry‑out (1 = non‑negative result)
                    reg [8:0] sum;
                    reg [7:0] new_upper;
                    reg       q_bit;
                    reg [15:0] sr_tmp;
                    reg [15:0] sr_next;

                    sum = {1'b0, SR[15:8]} + {1'b0, neg_divisor};
                    if (sum[8]) begin
                        new_upper = sum[7:0]; // subtraction succeeded
                        q_bit    = 1'b1;
                    end else begin
                        new_upper = SR[15:8]; // restore original upper bits
                        q_bit    = 1'b0;
                    end
                    // compose temporary shift register before the left shift
                    sr_tmp = {new_upper, SR[7:0]};
                    // shift left by one and insert the quotient bit at LSB
                    sr_next = sr_tmp << 1;
                    sr_next[0] = q_bit;
                    SR <= sr_next;

                    // capture the result after the 8th iteration
                    if (cnt == 3'd8) begin
                        // unsigned results are taken from the shift register *after* the final shift
                        quotient_u  <= sr_next[7:0];
                        remainder_u <= sr_next[15:8];
                        state       <= DONE;
                    end else begin
                        cnt <= cnt + 3'd1;
                    end
                end

                DONE: begin
                    // result is ready – keep it until the consumer acknowledges
                    if (res_ready) begin
                        res_valid <= 1'b0;
                        state     <= IDLE;
                    end else begin
                        // apply signed correction only once when we first enter DONE
                        // (the block is executed every cycle in DONE, but the same values are written)
                        reg [7:0] q_corr;
                        reg [7:0] r_corr;
                        if (sign_reg) begin
                            // quotient sign correction
                            q_corr = (dividend_neg ^ divisor_neg) ? -quotient_u : quotient_u;
                            // remainder sign correction (sign follows dividend)
                            r_corr = dividend_neg ? -remainder_u : remainder_u;
                        end else begin
                            q_corr = quotient_u;
                            r_corr = remainder_u;
                        end
                        result    <= {r_corr, q_corr};
                        res_valid <= 1'b1;
                    end
                end

                default: begin
                    state <= IDLE; // safety fallback
                end
            endcase
        end
    end

endmodule

module cla_16bit (
    input  [15:0] A,
    input  [15:0] B,
    input         Cin,
    output [15:0] Sum,
    output        Cout
);
    wire [15:0] G = A & B;
    wire [15:0] P = A ^ B;
    wire [16:0] C;
    assign C[0] = Cin;
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);
    assign C[5] = G[4] | (P[4] & C[4]);
    assign C[6] = G[5] | (P[5] & C[5]);
    assign C[7] = G[6] | (P[6] & C[6]);
    assign C[8] = G[7] | (P[7] & C[7]);
    assign C[9] = G[8] | (P[8] & C[8]);
    assign C[10] = G[9] | (P[9] & C[9]);
    assign C[11] = G[10] | (P[10] & C[10]);
    assign C[12] = G[11] | (P[11] & C[11]);
    assign C[13] = G[12] | (P[12] & C[12]);
    assign C[14] = G[13] | (P[13] & C[13]);
    assign C[15] = G[14] | (P[14] & C[14]);
    assign C[16] = G[15] | (P[15] & C[15]);
    assign Sum = P ^ C[15:0];
    assign Cout = C[16];
endmodule

