module adder_8bit (
    input  [7:0] a,
    input  [7:0] b,
    input        Cin,
    output [7:0] y,
    output       Co
);
    wire [8:0] c; // carry chain, c[0] is Cin, c[8] will be Co
    assign c[0] = Cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : fa
            wire sum, cout;
            assign sum  = a[i] ^ b[i] ^ c[i];
            assign cout = (a[i] & b[i]) | (a[i] & c[i]) | (b[i] & c[i]);
            assign y[i] = sum;
            assign c[i+1] = cout;
        end
    endgenerate

    assign Co = c[8];
endmodule

