rounds.vsl_text:
module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    // Binary sum of inputs (including carry) – 5 bits to capture overflow
    wire [4:0] raw = A + B + Cin; // raw sum
    // Detect if correction (add 6) is needed: true for raw > 9
    wire correction_needed;
    assign correction_needed = raw[4] | (raw[3] & (raw[2] | raw[1])); // correction condition
    // Apply BCD correction when needed
    reg [4:0] corrected;
    always @* begin
        if (correction_needed)
            corrected = raw + 5'd6; // add 6 for BCD correction
        else
            corrected = raw;        // no correction
    end
    // Final BCD digit (lower 4 bits)
    assign Sum  = corrected[3:0]; // BCD sum digit
    // Carry out: either correction was needed or there is an overflow from corrected sum
    assign Cout = correction_needed | corrected[4]; // carry out
endmodule

