# The FSM module detects the binary sequence 10011 on a serial input IN.
# It uses a Mealy architecture, so MATCH is asserted combinationally during the
# transition from state S4 to S1 when the final '1' of the pattern is received.
# Overlapping patterns are supported because after a match the machine moves to
# state S1 (the first '1' of a potential next pattern) rather than resetting to S0.
# Synchronous active‑high reset (RST) clears the state and forces MATCH low.

module fsm (
    input  logic CLK,
    input  logic RST,
    input  logic IN,
    output logic MATCH
);
    // State encoding using an enum for readability
    typedef enum logic [2:0] {
        S0 = 3'd0, // no bits matched
        S1 = 3'd1, // matched "1"
        S2 = 3'd2, // matched "10"
        S3 = 3'd3, // matched "100"
        S4 = 3'd4  // matched "1001"
    } state_t;

    state_t state, next_state;

    // Combinational next‑state logic (Mealy output is computed in the sequential block)
    always_comb begin
        unique case (state)
            S0:   next_state = (IN) ? S1 : S0;
            S1:   next_state = (IN) ? S1 : S2;
            S2:   next_state = (IN) ? S1 : S3;
            S3:   next_state = (IN) ? S4 : S0;
            S4:   next_state = (IN) ? S1 : S2; // on IN=1 we also produce a MATCH
            default: next_state = S0;
        endcase
    end

    // Sequential logic: state register and Mealy output
    always_ff @(posedge CLK) begin
        if (RST) begin
            state  <= S0;
            MATCH  <= 1'b0;
        end else begin
            state  <= next_state;
            // MATCH is high for one clock cycle when we are in S4 and IN=1
            MATCH  <= (state == S4 && IN == 1'b1);
        end
    end
endmodule

