module ring_counter (
    input  clk,
    input  reset,
    output [7:0] out
);
    // Internal state register
    reg [7:0] out_r;

    // Synchronous reset and rotate‑left logic
    always @(posedge clk) begin
        if (reset) begin
            out_r <= 8'b0000_0001; // reset pattern
        end else begin
            out_r <= {out_r[6:0], out_r[7]}; // rotate left
        end
    end

    // Drive the output
    assign out = out_r;
endmodule
